import csv,json
from pathlib import Path
from etymology_assignments import read_assignments
P=Path('curation/etymology-lab/indo-aryan-diversity-20260922')
rs=[{k:r[k] for k in ('ID','Language_ID','Form','Gloss','Source','Tags')} for r in csv.DictReader(open('cldf/forms.csv')) if 'rezaibaghbidi2003zargari[' in r['Source']]
assigned={r['Form_ID'] for r in read_assignments() if r['Status']=='accepted'};assigned.update(r['Child_ID'] for r in csv.DictReader(open('cldf/edges.csv')) if r['Rank']=='1')
groups=[
(['soy','sov','sovun','soyipey'],['to sleep','sleep!'],'13902','svapati','Turner explicitly gives European Romani sov sleeps under svapati/*supati, noting the historical coalescence of those present stems. Source sections2.3.13 and3.13.3 identify present soy- beside imperative sov/sovun;3.17.3.1 identifies the infinitive suffix -ipey. These are ordinary forms of one inherited verb, not the distinct old supta past stem.'),
(['ruy','ruv','ruvun','ruyipey'],['to cry; to weep','cry!'],'10840','rodati','Turner section1 explicitly gives European Romani rov weeps. Source sections2.3.13 and3.13.3 identify Zargari ruy- beside imperative ruv/ruvun and infinitive ruyipey. The local u vowel and v/y alternation are retained; this follows the Romani rodati family, not a new assignment to section2 rudati based only on vowel resemblance. Homonymous ruv wolf is excluded.'),
(['cʰin','cʰind','cʰindo','cʰindi','cʰinde','cʰinipey'],['to cut','cut'],'5046','*chindati','Turner gives southeastern European Romani čhin cut under *chindati/chinatti, explicitly allowing alternative origin from chinna. Retain that alternative in this family link. Source3.6.2 derives the perfect stem čhind- with -d;3.17.2.2 adds participial -o/-i/-e, and3.17.3.1 gives the infinitive. These Zargari participles are based on its productive perfect stem, not automatically assigned to an ancient chinna participle node.'),
(['dikʰ','dikʰl'],['see!','to see; to look'],'6507-2','*dekṣati','Turner section2 explicitly gives European Romani dikh and explains its i as an irregular e-to-i change or influence of diṭṭha, rather than a direct *dṛkṣati continuation. Source3.6.2 explicitly pairs dikh-/dikhl- as present/perfect stems and3.13.1 gives the imperative.'),
(['pucʰ','puśl','puślom','puślān'],['ask!','to ask','I asked','you asked'],'8352','pṛcchati','Turner gives Romani phuč-, Greek Romani puč-, Rumanian puš- and Armenian pučh- asks. The source explicitly pairs pučh-/pušl- as present/perfect stems and gives pušlom/pušlān as past1sg/2sg. Aspiration placement and the perfect affricate-to-sibilant alternation are source-supported, not reconstructed from spelling similarity.')]
a=[]
for fs,gs,pa,label,ev in groups:
 for r in rs:
  if r['ID'] not in assigned and r['Form'] in fs and r['Gloss'] in gs:a.append(dict(record=r,parent=pa,kind='reflex',citation=f'CDIAL[{pa} and addenda];'+r['Source'],evidence=ev+' Exact source morphology, stress, gloss and citation are preserved.'))
assert len(a)==22,len(a)
(P/'pass028-decisions.json').write_text(json.dumps(dict(accepted=a,held=[]),ensure_ascii=False,indent=2)+'\n')
locators={s for x in a for s in x['record']['Source'].split(';')};aud=[r for r in csv.DictReader(open('data/other/forms/raw_data/20260825-rezai-baghbidi-zargari-audit.csv')) if r['Source'] in locators];(P/'pass028-source-audit.json').write_text(json.dumps(aud,ensure_ascii=False,indent=2)+'\n')
lines=['# Zargari: verb stems, imperatives and inflections','','22 records / 22 reflex rows across five verb families. Already-linked records excluded using current compiled graph and accepted overlay.','','| # | Zargari forms and meanings | Proposed etymology | Evidence |','|---|---|---|---|']
for i,(fs,gs,pa,label,ev) in enumerate(groups,1):
 label=label.replace('*',r'\*');n=sum(x['parent']==pa for x in a);lines.append(f'| {i} | **{" / ".join(fs)}** ‘{" / ".join(gs)}’ ({n}) | **{label}**, CDIAL **{pa}** | {ev} |')
lines+=['','Primary grammar read directly using the existing glyph-decoder, without running its importer or changing lexical files: zargari-primary-pages.json. Printed p138 section3.6.2 defines present/perfect stems; p141 section3.13.3 defines the v/y alternation and imperative forms; p142 sections3.17.2–3 define participles and infinitives. Source section2.3.23 also supplies the ask preterites.','', 'Excluded: wolf ruv, negative/subjunctive multi-part forms, analytic predicates with som, the productive mediopassive čhindiv/čhindil, and causatives. These require their own morphology/derivation analysis. No new donor or lexeme nodes, source re-ingestion, transcription repairs or rebuild. Prior holds remain.','', 'Search006–007 and primary005–006 preserve dictionary discovery and full shortlisted articles. The cut-family chinna alternative is explicitly retained, not claimed resolved.','', 'Validation and save status: pending.'];(P/'pass028-review.md').write_text('\n'.join(lines)+'\n');print(len(a),'accepted')
